import {bindHost} from './host.js';
let program=null,host=null;
export async function loadCallCenter(value){if(program)return program;host=value;bindHost(value);const [entry,routes]=await Promise.all([import('./program/extensions/call-center/index.js'),import('./program/src/api/routes/telephony.js')]);program={entry:entry.default,routes,check:value.check};return program;}
export default {id:'call-center',name:'Call Center',version:'1.1.0',async register(api){
 if(!api.callCenterHost){api.log('warn','Update Girru before using Call Center from the Store.');return;}
 const p=await api.callCenterHost.load(),data=host.core['src/db/index.js'].getDatabase();
 const providers=[{"id": "provider_twilio", "provider_name": "twilio", "display_name": "Twilio", "enabled": 1, "is_default": 1, "config": null, "pricing_info": "{\"base\":\"$0\",\"perMinute\":\"$0.0085\",\"setup\":\"$1.00\",\"monthly\":\"$1.15/number\",\"currency\":\"USD\"}", "capabilities": "[\"voice\",\"sms\",\"video\",\"recording\",\"transcription\",\"conference\",\"ivr\"]", "status": "active", "last_health_check": null, "health_status": null, "created_at": "2026-11-05 21:36:06", "updated_at": "2026-11-05 21:36:06"}, {"id": "provider_teams", "provider_name": "microsoft_teams", "display_name": "Microsoft Teams Phone", "enabled": 0, "is_default": 0, "config": null, "pricing_info": "{\"base\":\"$8-12/user/month\",\"perMinute\":\"$0.03-0.04\",\"setup\":\"Free\",\"domestic\":\"$12/user/month (3000 min)\",\"international\":\"$24/user/month (1200 min)\",\"currency\":\"USD\"}", "capabilities": "[\"voice\",\"video\",\"recording\",\"conference\",\"screen_share\",\"transfer\",\"hold\",\"pstn\"]", "status": "active", "last_health_check": null, "health_status": null, "created_at": "2026-11-05 21:36:06", "updated_at": "2026-11-05 21:36:06"}, {"id": "provider_vonage", "provider_name": "vonage", "display_name": "Vonage (Nexmo)", "enabled": 0, "is_default": 0, "config": null, "pricing_info": "{\"base\":\"$0\",\"perMinute\":\"$0.004\",\"setup\":\"$0.90\",\"monthly\":\"$0.90/number\",\"currency\":\"USD\"}", "capabilities": "[\"voice\",\"sms\",\"recording\",\"conference\",\"ivr\",\"transfer\",\"hold\"]", "status": "active", "last_health_check": null, "health_status": null, "created_at": "2026-11-05 21:36:06", "updated_at": "2026-11-05 21:36:06"}];
 if(!data.prepare('SELECT COUNT(*) AS n FROM app_call_center__telephony_providers').get().n){for(const row of providers){const keys=Object.keys(row);data.prepare('INSERT INTO app_call_center__telephony_providers ('+keys.join(',')+') VALUES ('+keys.map(()=>'?').join(',')+')').run(...keys.map(k=>row[k]));}}
 await p.entry.register({...api,registerRoutes(fn){api.registerRoutes(async scope=>{scope.addHook('onRequest',async()=>p.check());await fn(scope);});}});
},async onDisable(api){try{if(program)await program.entry.onDisable(api);}finally{host?.retire();}}};
